def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    my_d = sum(1 for x in me if x == 'D')

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break
    if run_d >= 5:
        return 'D'

    if n >= 8 and opp_c <= 1:
        return 'D'

    reactive = False
    for i in range(n - 1):
        if me[i] == 'D' and op[i] == 'C' and op[i + 1] == 'D':
            reactive = True
            break

    if reactive:
        return 'C'

    if my_d >= 2:
        return 'D'

    if me[-1] == 'D':
        return 'C'

    if n == 5 or n == 15:
        return 'D'

    return 'C'
